$sessionMinutes=24;
try{$value=Database::connection()->query("SELECT value FROM settings WHERE key='session_timeout_minutes'")->fetchColumn();if($value!==false)$sessionMinutes=max(0,(int)$value);}catch(Throwable){}
$sessionSeconds=$sessionMinutes===0?315360000:$sessionMinutes*60;
ini_set('session.gc_maxlifetime',(string)$sessionSeconds);
session_name('bitchin_kitchen'); session_start(['cookie_lifetime'=>$sessionMinutes===0?$sessionSeconds:0,'cookie_httponly'=>true,'cookie_samesite'=>'Lax','cookie_secure'=>isset($_SERVER['HTTPS'])]);
if(!empty($_SESSION['user_id'])&&$sessionMinutes>0&&!empty($_SESSION['_last_activity'])&&time()-$_SESSION['_last_activity']>$sessionSeconds){unset($_SESSION['user_id']);session_regenerate_id(true);$_SESSION['_flash'][]=['error','Your session expired due to inactivity. Please sign in again.'];}
if(!empty($_SESSION['user_id']))$_SESSION['_last_activity']=time();

function e(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function url(string $path=''): string { return rtrim((string)App\Env::get('APP_URL',''),'/').$path; }
function redirect(string $to): never { header('Location: '.$to); exit; }
function abort(int $code, string $message=''): never { http_response_code($code); App\View::render('error',['code'=>$code,'message'=>$message ?: ($code===403?'That is not yours to edit.':'Page not found.')]); exit; }
function flash(string $message, string $type='success'): void { $_SESSION['_flash'][]=[$type,$message]; }
function csrf(): string { return '<input type="hidden" name="_token" value="'.e(App\Csrf::token()).'">'; }
function method_is(string $method): bool { return $_SERVER['REQUEST_METHOD'] === $method; }
function recipe(int $id, bool $includePrivate=false): array {
    $sql='SELECT r.*,u.name owner_name,c.name cuisine_name,(SELECT filename FROM recipe_photos WHERE recipe_id=r.id ORDER BY sort_order,id LIMIT 1) thumbnail FROM recipes r JOIN users u ON u.id=r.user_id LEFT JOIN cuisines c ON c.id=r.cuisine_id WHERE r.id=?';
    if(!$includePrivate) $sql.=' AND r.is_public=true'; $q=Database::connection()->prepare($sql); $q->execute([$id]); return $q->fetch() ?: abort(404);
}
function save_photos(int $recipeId): void {
    if(empty($_FILES['photos']['name'][0])) return;
    $max=(int)Env::get('UPLOAD_MAX_FILE_MB',8)*1024*1024; $finfo=new finfo(FILEINFO_MIME_TYPE); $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];
    $order=(int)Database::connection()->query('SELECT COALESCE(MAX(sort_order),-1)+1 FROM recipe_photos WHERE recipe_id='.(int)$recipeId)->fetchColumn();
    foreach($_FILES['photos']['tmp_name'] as $i=>$tmp){ if($_FILES['photos']['error'][$i]!==UPLOAD_ERR_OK) continue; if($_FILES['photos']['size'][$i]>$max) continue; $mime=$finfo->file($tmp); if(!isset($allowed[$mime])) continue; $name=bin2hex(random_bytes(16)).'.'.$allowed[$mime]; if(move_uploaded_file($tmp,__DIR__.'/uploads/'.$name)){ $q=Database::connection()->prepare('INSERT INTO recipe_photos(recipe_id,filename,sort_order) VALUES(?,?,?)'); $q->execute([$recipeId,$name,$order++]); } }
}
function taxonomy_options(int $recipeId=0): array {
    $selected=[];if($recipeId){$q=Database::connection()->prepare('SELECT tag_id FROM recipe_tags WHERE recipe_id=?');$q->execute([$recipeId]);$selected=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));}
    return ['cuisines'=>Database::connection()->query('SELECT * FROM cuisines ORDER BY name')->fetchAll(),'tags'=>Database::connection()->query('SELECT * FROM tags ORDER BY name')->fetchAll(),'selectedTags'=>$selected];
}
function sync_recipe_tags(int $recipeId, array $tagIds, array $previous=[]): void {
    $tagIds=array_unique(array_filter(array_map('intval',$tagIds),fn($id)=>$id>0));$pdo=Database::connection();$q=$pdo->prepare('DELETE FROM recipe_tags WHERE recipe_id=?');$q->execute([$recipeId]);
    $check=$pdo->prepare('SELECT is_active FROM tags WHERE id=?');$insert=$pdo->prepare('INSERT INTO recipe_tags(recipe_id,tag_id) VALUES(?,?) ON CONFLICT DO NOTHING');
    foreach($tagIds as $tagId){$check->execute([$tagId]);$active=$check->fetchColumn();if($active===true||$active==='t'||$active===1||$active==='1'||in_array($tagId,$previous,true))$insert->execute([$recipeId,$tagId]);}
}

$path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH) ?: '/';
try {
try {
