if($path==='/' && method_is('GET')) {
    $q=trim($_GET['q']??''); $mine=($_GET['mine']??'')==='1'; $user=Auth::user(); $all=isset($_GET['all'])&&in_array($user['role']??'', ['admin','superadmin'],true);$cuisineId=(int)($_GET['cuisine']??0);$filterTags=array_values(array_unique(array_filter(array_map('intval',$_GET['tags']??[]))));
    if(!$user) { View::render('auth/login'); return; }
    $where=$all?'true':($mine?'r.user_id=:uid':'r.is_public=true'); $params=$mine&&!$all?['uid'=>$user['id']]:[];
    if($q!==''){ $where.=" AND r.search_vector @@ websearch_to_tsquery('english',:q)"; $params['q']=$q; }
    if($cuisineId){$where.=' AND r.cuisine_id=:cuisine';$params['cuisine']=$cuisineId;}if($filterTags){$holders=[];foreach($filterTags as $i=>$tagId){$key='tag'.$i;$holders[]=':'.$key;$params[$key]=$tagId;}$where.=' AND r.id IN (SELECT recipe_id FROM recipe_tags WHERE tag_id IN ('.implode(',',$holders).') GROUP BY recipe_id HAVING count(DISTINCT tag_id)='.count($filterTags).')';}
    $sql="SELECT r.*,u.name owner_name,c.name cuisine_name,p.filename thumbnail,(SELECT string_agg(t.name,', ' ORDER BY t.name) FROM recipe_tags rt JOIN tags t ON t.id=rt.tag_id WHERE rt.recipe_id=r.id) tag_names FROM recipes r JOIN users u ON u.id=r.user_id LEFT JOIN cuisines c ON c.id=r.cuisine_id LEFT JOIN LATERAL (SELECT filename FROM recipe_photos WHERE recipe_id=r.id ORDER BY sort_order,id LIMIT 1)p ON true WHERE $where ORDER BY ".($q!==''?"ts_rank(r.search_vector,websearch_to_tsquery('english',:q)) DESC,":"").' r.updated_at DESC LIMIT 60';
    $st=Database::connection()->prepare($sql); $st->execute($params);$cuisines=Database::connection()->query('SELECT * FROM cuisines WHERE is_active=true ORDER BY name')->fetchAll();$tags=Database::connection()->query('SELECT * FROM tags WHERE is_active=true ORDER BY name')->fetchAll(); View::render('home',['recipes'=>$st->fetchAll(),'query'=>$q,'mine'=>$mine,'all'=>$all,'cuisines'=>$cuisines,'tags'=>$tags,'cuisineId'=>$cuisineId,'filterTags'=>$filterTags]);
} elseif($path==='/login' && method_is('GET')) View::render('auth/login');
elseif($path==='/login' && method_is('POST')) { Csrf::verify(); if(Auth::login(trim($_POST['name']??''),$_POST['password']??''))redirect('/');flash('Username or password was incorrect.','error');redirect('/login'); }
elseif($path==='/logout' && method_is('POST')) { Csrf::verify(); session_destroy();redirect('/'); }
elseif($path==='/recipes/new' && method_is('GET')) { Auth::requireUser();$forkId=(int)($_GET['fork']??0);$photos=[];if($forkId){$source=recipe($forkId);$draft=['title'=>$source['title'].' — my version','summary'=>$source['summary'],'ingredients'=>$source['ingredients'],'instructions'=>$source['instructions'],'notes'=>$source['notes'],'is_public'=>true,'forked_from_id'=>$source['id'],'cuisine_id'=>$source['cuisine_id']];$q=Database::connection()->prepare('SELECT * FROM recipe_photos WHERE recipe_id=? ORDER BY sort_order,id');$q->execute([$forkId]);$photos=$q->fetchAll();$tax=taxonomy_options($forkId);}else{$draft=['title'=>'','summary'=>'','ingredients'=>'','instructions'=>'','notes'=>'','is_public'=>true,'forked_from_id'=>null,'cuisine_id'=>null];$tax=taxonomy_options();}View::render('recipes/form',array_merge(['recipe'=>$draft,'photos'=>$photos,'action'=>'/recipes'],$tax)); }
elseif($path==='/recipes' && method_is('POST')) { $u=Auth::requireUser();Csrf::verify();$title=trim($_POST['title']??'');$ingredients=trim($_POST['ingredients']??'');$instructions=trim($_POST['instructions']??'');$sourceId=(int)($_POST['forked_from_id']??0);if($sourceId)recipe($sourceId);if($title===''||$ingredients===''||$instructions===''){flash('Title, ingredients, and instructions are required.','error');redirect('/recipes/new'.($sourceId?'?fork='.$sourceId:''));}$q=Database::connection()->prepare('INSERT INTO recipes(user_id,forked_from_id,cuisine_id,title,summary,ingredients,instructions,notes,is_public)VALUES(?,?,?,?,?,?,?,?,?) RETURNING id');$q->execute([$u['id'],$sourceId?:null,(int)($_POST['cuisine_id']??0)?:null,$title,trim($_POST['summary']??''),$ingredients,$instructions,trim($_POST['notes']??''),isset($_POST['is_public'])]);$id=(int)$q->fetchColumn();sync_recipe_tags($id,$_POST['tags']??[]);if($sourceId){$q=Database::connection()->prepare('INSERT INTO recipe_photos(recipe_id,filename,sort_order) SELECT ?,filename,sort_order FROM recipe_photos WHERE recipe_id=?');$q->execute([$id,$sourceId]);}save_photos($id);flash('Recipe is fresh from the oven!');redirect('/recipes/'.$id); }
elseif(preg_match('#^/recipes/(\d+)$#',$path,$m) && method_is('GET')) { $u=Auth::user();$r=recipe((int)$m[1],true);$admin=$u&&in_array($u['role'],['admin','superadmin'],true);if(!$r['is_public']&&(!$u||(int)$u['id']!==(int)$r['user_id'])&&!$admin)abort(404);$q=Database::connection()->prepare('SELECT * FROM recipe_photos WHERE recipe_id=? ORDER BY sort_order,id');$q->execute([$r['id']]);$photos=$q->fetchAll();$q=Database::connection()->prepare('SELECT t.* FROM recipe_tags rt JOIN tags t ON t.id=rt.tag_id WHERE rt.recipe_id=? ORDER BY t.name');$q->execute([$r['id']]);View::render('recipes/show',['recipe'=>$r,'photos'=>$photos,'recipeTags'=>$q->fetchAll()]); }
elseif(preg_match('#^/recipes/(\d+)/edit$#',$path,$m) && method_is('GET')) { $u=Auth::requireUser();$r=recipe((int)$m[1],true);if((int)$u['id']!==(int)$r['user_id'])abort(403);$q=Database::connection()->prepare('SELECT * FROM recipe_photos WHERE recipe_id=? ORDER BY sort_order,id');$q->execute([$r['id']]);View::render('recipes/form',array_merge(['recipe'=>$r,'photos'=>$q->fetchAll(),'action'=>'/recipes/'.$r['id']],taxonomy_options((int)$r['id']))); }
elseif(preg_match('#^/recipes/(\d+)$#',$path,$m) && method_is('POST')) { $u=Auth::requireUser();Csrf::verify();$r=recipe((int)$m[1],true);if((int)$u['id']!==(int)$r['user_id'])abort(403);$q=Database::connection()->prepare('UPDATE recipes SET title=?,summary=?,ingredients=?,instructions=?,notes=?,is_public=?,updated_at=NOW() WHERE id=?');$q->execute([trim($_POST['title']??''),trim($_POST['summary']??''),trim($_POST['ingredients']??''),trim($_POST['instructions']??''),trim($_POST['notes']??''),isset($_POST['is_public']),$r['id']]);$remove=array_unique(array_map('intval',$_POST['remove_photos']??[]));foreach($remove as $photoId){$q=Database::connection()->prepare('DELETE FROM recipe_photos WHERE id=? AND recipe_id=? RETURNING filename');$q->execute([$photoId,$r['id']]);$filename=$q->fetchColumn();if($filename){$check=Database::connection()->prepare('SELECT count(*) FROM recipe_photos WHERE filename=?');$check->execute([$filename]);if((int)$check->fetchColumn()===0){$file=__DIR__.'/uploads/'.basename($filename);if(is_file($file))unlink($file);}}}$primary=(int)($_POST['primary_photo']??0);if($primary&&!in_array($primary,$remove,true)){$q=Database::connection()->prepare('SELECT count(*) FROM recipe_photos WHERE id=? AND recipe_id=?');$q->execute([$primary,$r['id']]);if((int)$q->fetchColumn()===1){$q=Database::connection()->prepare('UPDATE recipe_photos SET sort_order=sort_order+1 WHERE recipe_id=?');$q->execute([$r['id']]);$q=Database::connection()->prepare('UPDATE recipe_photos SET sort_order=0 WHERE id=? AND recipe_id=?');$q->execute([$primary,$r['id']]);}}save_photos((int)$r['id']);flash('Recipe updated.');redirect('/recipes/'.$r['id']); }
elseif(preg_match('#^/recipes/(\d+)/fork$#',$path,$m) && method_is('POST')) { Auth::requireUser();Csrf::verify();$r=recipe((int)$m[1]);redirect('/recipes/new?fork='.$r['id']); }
elseif(preg_match('#^/recipes/(\d+)/delete$#',$path,$m) && method_is('POST')) { $u=Auth::requireUser();Csrf::verify();$r=recipe((int)$m[1],true);$canDelete=(int)$u['id']===(int)$r['user_id']||in_array($u['role'],['admin','superadmin'],true);if(!$canDelete)abort(403);$q=Database::connection()->prepare('SELECT filename FROM recipe_photos WHERE recipe_id=?');$q->execute([$r['id']]);$filenames=$q->fetchAll(PDO::FETCH_COLUMN);$q=Database::connection()->prepare('DELETE FROM recipes WHERE id=?');$q->execute([$r['id']]);foreach($filenames as $filename){$q=Database::connection()->prepare('SELECT count(*) FROM recipe_photos WHERE filename=?');$q->execute([$filename]);if((int)$q->fetchColumn()===0){$file=__DIR__.'/uploads/'.basename($filename);if(is_file($file))unlink($file);}}flash('Recipe deleted.');redirect('/'); }
elseif($path==='/admin/users' && method_is('GET')) { $u=Auth::requireAdmin();$users=Database::connection()->query('SELECT id,name,role,created_at FROM users ORDER BY created_at')->fetchAll();View::render('admin/users',['users'=>$users,'current'=>$u]); }
elseif($path==='/admin/users' && method_is('POST')) { Auth::requireAdmin();Csrf::verify();$name=trim($_POST['name']??'');$password=$_POST['password']??'';$role=$_POST['role']??'user';if(strlen($name)<2||strlen($name)>100||strlen($password)<8||!in_array($role,['user','admin'],true)){flash('Use a unique username, a password of at least 8 characters, and a valid role.','error');redirect('/admin/users');}try{$q=Database::connection()->prepare('INSERT INTO users(name,password_hash,role) VALUES(?,?,?)');$q->execute([$name,password_hash($password,PASSWORD_DEFAULT),$role]);flash('User created.');}catch(PDOException){flash('That username is already in use.','error');}redirect('/admin/users'); }
elseif(preg_match('#^/admin/users/(\d+)/role$#',$path,$m)&&method_is('POST')) { $u=Auth::requireAdmin();Csrf::verify();$role=$_POST['role']??'user';if(!in_array($role,['admin','user'],true))abort(422);$target=(int)$m[1];if($target===(int)$u['id'])abort(422,'You cannot change your own role.');$q=Database::connection()->prepare("UPDATE users SET role=? WHERE id=? AND role<>'superadmin'");$q->execute([$role,$target]);flash('User role updated.');redirect('/admin/users'); }
elseif(preg_match('#^/admin/users/(\d+)/password$#',$path,$m)&&method_is('POST')) { $u=Auth::requireAdmin();Csrf::verify();$password=$_POST['password']??'';if(strlen($password)<8){flash('Passwords must contain at least 8 characters.','error');redirect('/admin/users');}$target=(int)$m[1];$q=Database::connection()->prepare('SELECT role FROM users WHERE id=?');$q->execute([$target]);$targetRole=$q->fetchColumn();if(!$targetRole)abort(404);if($targetRole==='superadmin'&&($u['role']!=='superadmin'||$target!==(int)$u['id']))abort(403,'The superadmin password cannot be changed by another account.');$q=Database::connection()->prepare('UPDATE users SET password_hash=? WHERE id=?');$q->execute([password_hash($password,PASSWORD_DEFAULT),$target]);flash('Password updated.');redirect('/admin/users'); }
elseif($path==='/admin/taxonomy'&&method_is('GET')) { Auth::requireAdmin();View::render('admin/taxonomy',['cuisines'=>Database::connection()->query('SELECT * FROM cuisines ORDER BY name')->fetchAll(),'tags'=>Database::connection()->query('SELECT * FROM tags ORDER BY name')->fetchAll()]); }
elseif($path==='/admin/taxonomy'&&method_is('POST')) { Auth::requireAdmin();Csrf::verify();$type=$_POST['type']??'';$table=$type==='cuisine'?'cuisines':($type==='tag'?'tags':null);$name=trim($_POST['name']??'');if(!$table||strlen($name)<2||strlen($name)>80){flash('Enter a valid name of 2–80 characters.','error');redirect('/admin/taxonomy');}try{$q=Database::connection()->prepare("INSERT INTO $table(name) VALUES(?)");$q->execute([$name]);flash(ucfirst($type).' added.');}catch(PDOException){flash('That name already exists.','error');}redirect('/admin/taxonomy'); }
